styleTexts.text:
.at-surface * {
    cursor: default;
    vertical-align: top;
    overflow: visible;
}
.at-surface-svg text {
    dominant-baseline: alphabetic;
    white-space:pre;
}

@font-face {
    font-display: block;
    font-family: 'alphaTab';
    src: url("/at/font/Bravura.woff2") format('woff2'),url("/at/font/Bravura.woff") format('woff'),url("/at/font/Bravura.otf") format('opentype');
    font-weight: normal;
    font-style: normal;
}
.at-surface.at .at {
    font-family: 'alphaTab';
    speak: none;
    font-style: normal;
    font-weight: normal;
    font-variant: normal;
    text-transform: none;
    line-height: 1;
    line-height: 1;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-size: 36px;
    overflow: visible !important;
}
